// Parse the HuggingFace Inference API response and extract the script text.
// The API returns: [{"generated_text": "..."}] or {"generated_text": "..."}
const item = $input.first();
const data = item.json;

let scriptText = '';
if (Array.isArray(data) && data[0] && data[0].generated_text) {
  scriptText = data[0].generated_text;
} else if (data.generated_text) {
  scriptText = data.generated_text;
} else if (typeof data === 'string') {
  scriptText = data;
} else {
  // Last-resort: stringify and look for generated_text key
  const raw = JSON.stringify(data);
  const m = raw.match(/"generated_text"\s*:\s*"((?:[^"\\]|\\.)*?)"/);
  if (m) scriptText = m[1].replace(/\\n/g, '\n').replace(/\\t/g, '\t');
}

// If model echoed the prompt before answering, take only the part after
if (scriptText.includes('<|assistant|>')) {
  scriptText = scriptText.split('<|assistant|>').pop();
}
if (scriptText.includes('[/INST]')) {
  scriptText = scriptText.split('[/INST]').pop();
}

scriptText = scriptText.trim();

// Fallback: if API call failed or returned empty, use a placeholder script
if (!scriptText) {
  scriptText = `HOOK: Your life changes the moment you decide to level up.\nBODY: Most people wait for the perfect moment. Successful people create it. Every small action today builds your future.\nCTA: Start right now. Drop a comment: what is your goal?`;
}

return [{
  json: {
    ...item.json,
    script_text: scriptText
  }
}];

// Build timestamp-based file paths for all intermediate and output files.
const item = $input.first();
const ts = Date.now();
const outDir = item.json.output_dir;
const scriptsDir = item.json.scripts_dir;

return [{
  json: {
    ...item.json,
    timestamp: ts,
    script_file:      `${outDir}\\script_${ts}.txt`,
    voice_file:       `${outDir}\\voice_${ts}.mp3`,
    bg_video_file:    `${outDir}\\bg_video_${ts}.mp4`,
    final_video_file: `${outDir}\\final_short_${ts}.mp4`,
    scripts_dir:      scriptsDir
  }
}];

// Convert the script text string to binary data so the
// Write Binary File node can save it as a .txt file on disk.
const item = $input.first();
const scriptText = item.json.script_text || '';

const buffer = Buffer.from(scriptText, 'utf-8');
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  'script.txt',
  'text/plain'
);

return [{
  json: item.json,
  binary: {
    data: binaryData
  }
}];

// Extract a usable video download URL from the Pixabay API response.
// Pixabay returns: { hits: [{ videos: { medium: { url: '...' }, small: { url: '...' } } }] }
const item = $input.first();
const hits = item.json.hits || [];

let videoUrl = '';
if (hits.length > 0) {
  const hit = hits[0];
  const vids = hit.videos || {};
  // Prefer medium (1280px wide), fall back to small (960px)
  videoUrl =
    (vids.medium && vids.medium.url) ||
    (vids.small  && vids.small.url)  ||
    (vids.large  && vids.large.url)  ||
    '';
}

if (!videoUrl) {
  // Fallback: use a public domain sample video hosted on n8n docs
  videoUrl = 'https://sample-videos.com/video321/mp4/720/big_buck_bunny_720p_1mb.mp4';
}

return [{
  json: {
    ...item.json,
    bg_video_url: videoUrl,
    has_video: videoUrl !== ''
  }
}];

