// Parse the HuggingFace response and extract YouTube metadata.
const item = $input.first();
const data = item.json;

let metaText = '';
if (Array.isArray(data) && data[0] && data[0].generated_text) {
  metaText = data[0].generated_text;
} else if (data.generated_text) {
  metaText = data.generated_text;
}

// Strip any prompt echo
if (metaText.includes('<|assistant|>')) {
  metaText = metaText.split('<|assistant|>').pop();
}
if (metaText.includes('[/INST]')) {
  metaText = metaText.split('[/INST]').pop();
}
metaText = metaText.trim();

let title = '';
let description = '';
let tags = [];

try {
  // Try to extract a JSON object from the response
  const jsonMatch = metaText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    title       = parsed.title       || '';
    description = parsed.description || '';
    tags        = Array.isArray(parsed.tags) ? parsed.tags : [];
  }
} catch (e) {
  // Fallback: regex extraction
  const tm = metaText.match(/"title"\s*:\s*"([^"]+)"/);
  const dm = metaText.match(/"description"\s*:\s*"([^"]+)"/);
  if (tm) title       = tm[1];
  if (dm) description = dm[1];
}

// Final fallbacks if model returned nothing useful
const topicClean = (item.json.topic || 'motivation').replace(/\s+/g, '');
if (!title)       title       = `🔥 ${item.json.topic} — Change Your Life | #Shorts`;
if (!description) description = `${item.json.script_text}\n\n#Shorts #Motivation #${topicClean} #SuccessMindset`;
if (!tags.length) tags        = ['Shorts', 'Motivation', item.json.topic, 'SuccessMindset', 'YouTube Shorts'];

return [{
  json: {
    ...item.json,
    yt_title:       title,
    yt_description: description,
    yt_tags:        tags
  }
}];
